    {"check": "Check if the solver confuses 'adherent clot' (Forrest IIb, intermediate risk) with a low-risk finding.", "status": "fail", "note": "Adherent clot typically requires endoscopic therapy and is not low-risk."},
    {"check": "Check if the solver identifies that 'visible bleeding vessel' (Forrest IIa) is high-risk for rebleeding.", "status": "pass", "note": "Visible vessel is an indication for endoscopic intervention, not low risk."},
    {"check": "Check if the solver incorrectly associates 'arteriovenous malformation' with a clean-based ulcer.", "status": "fail", "note": "AVMs are a different etiology and usually require embolization, not classified under Forrest."}
  ],
  "potential_errors": [
    "Assuming adherent clot indicates low rebleeding risk (Forrest IIb is higher risk than III).",
